-- ingest_site v1 (issue #95): the brand's website read as a site, home page plus key subpages, through the source
-- adapter registry (worker/sources/site.ts). The spec below is worker/engine/seed.ts INGEST_SITE, byte for byte;
-- worker-site-ingest.test.ts fails if the two drift apart. It reuses the prompt ingest.extract_facts seeded by 010.
-- Additive and safe to re-run. run_steps.type gains 'source' (the new step type that calls the source adapter registry).
alter table public.run_steps drop constraint if exists run_steps_type_check;
alter table public.run_steps add constraint run_steps_type_check check (type in ('fetch','source','llm','code','write','map'));
insert into public.workflow_defs (id, version, spec, status) values ('ingest_site', 1, $spec${"id":"ingest_site","version":1,"title":"Read the website","concurrency":"parallel","retries":{"limit":2,"delay":"5 seconds","backoff":"exponential"},"steps":[{"id":"read","type":"source","label":"Reading your site","source":"site","url":"$input.url","website":"$input.website","subpages":3,"maxChars":20000,"excerptChars":14000},{"id":"extract","type":"map","label":"Finding facts on each page","over":"$steps.read.pages","max":4,"step":{"id":"extract_page","type":"llm","label":"Finding facts","prompt":"ingest.extract_facts","json":true,"vars":{"brand_name":"$input.brandName","max_quote":"$const.MAX_QUOTE","sections":"$const.SECTIONS"},"user":"Page title: {{title}}\nURL: {{url}}\n\n{{text}}","userVars":{"title":"$input.item.title","url":"$input.item.url","text":"$input.item.excerpt"}}},{"id":"check","type":"code","label":"Checking every quote against its page","fn":"keep_quoted_facts_per_page","args":{"pages":"$steps.read.pages","extracts":"$steps.extract"}},{"id":"save","type":"write","label":"Saving the facts","op":"save_site_facts","args":{"sourceId":"$input.sourceId","pages":"$steps.check","link":"$input.url","website":"$input.website"}}],"output":"$steps.save","onFailure":{"op":"mark_source_failed","args":{"sourceId":"$input.sourceId"}}}$spec$::jsonb, 'active')
on conflict (id, version) do nothing;
